     1	<!DOCTYPE html>
     2	<html lang="en">
     3	<head>
     4	<meta charset="utf-8">
     5	<meta name="viewport" content="width=device-width, initial-scale=1">
     6	<title>Tetris</title>
     7	<style>
     8	  :root {
     9	    --cell: 28px;
    10	    --bg: #14161c;
    11	    --panel: #1d2029;
    12	    --grid: #262a35;
    13	    --text: #e8eaf0;
    14	    --muted: #8a90a0;
    15	  }
    16	  * { box-sizing: border-box; }
    17	  body {
    18	    margin: 0;
    19	    min-height: 100vh;
    20	    display: flex;
    21	    align-items: center;
    22	    justify-content: center;
    23	    background: var(--bg);
    24	    color: var(--text);
    25	    font: 14px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    26	  }
    27	  .game {
    28	    display: flex;
    29	    gap: 20px;
    30	    align-items: flex-start;
    31	    padding: 16px;
    32	  }
    33	  .board {
    34	    display: grid;
    35	    grid-template-columns: repeat(10, var(--cell));
    36	    grid-template-rows: repeat(20, var(--cell));
    37	    gap: 1px;
    38	    padding: 1px;
    39	    background: var(--grid);
    40	    border: 2px solid #3a3f4d;
    41	    border-radius: 4px;
    42	    position: relative;
    43	  }
    44	  .cell { background: var(--bg); }
    45	  .side {
    46	    display: flex;
    47	    flex-direction: column;
    48	    gap: 12px;
    49	    min-width: 140px;
    50	  }
    51	  .box {
    52	    background: var(--panel);
    53	    border-radius: 6px;
    54	    padding: 10px 12px;
    55	  }
    56	  .label {
    57	    font-size: 11px;
    58	    text-transform: uppercase;
    59	    letter-spacing: 0.08em;
    60	    color: var(--muted);
    61	  }
    62	  .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
    63	  .preview {
    64	    display: grid;
    65	    grid-template-columns: repeat(4, 18px);
    66	    grid-template-rows: repeat(2, 18px);
    67	    gap: 1px;
    68	    margin-top: 8px;
    69	  }
    70	  .preview .mini { background: transparent; }
    71	  .help { color: var(--muted); font-size: 12px; }
    72	  .help kbd {
    73	    background: #2b2f3a;
    74	    border-radius: 3px;
    75	    padding: 0 4px;
    76	    font: inherit;
    77	    color: var(--text);
    78	  }
    79	  .overlay {
    80	    position: absolute;
    81	    inset: 0;
    82	    display: flex;
    83	    flex-direction: column;
    84	    align-items: center;
    85	    justify-content: center;
    86	    gap: 10px;
    87	    background: rgba(10, 11, 15, 0.78);
    88	    font-size: 20px;
    89	    font-weight: 600;
    90	  }
    91	  .overlay button {
    92	    font: inherit;
    93	    font-size: 14px;
    94	    padding: 6px 14px;
    95	    border: 0;
    96	    border-radius: 4px;
    97	    background: #4a8cff;
    98	    color: #fff;
    99	    cursor: pointer;
   100	  }
   101	  .overlay[hidden] { display: none; }
   102	
   103	  /* Piece colours */
   104	  .p-I { background: #30c7e6; }
   105	  .p-O { background: #f2d33a; }
   106	  .p-T { background: #a35ee0; }
   107	  .p-S { background: #4ccf5a; }
   108	  .p-Z { background: #e8474a; }
   109	  .p-J { background: #3b6ee8; }
   110	  .p-L { background: #f09a2e; }
   111	</style>
   112	</head>
   113	<body>
   114	<div class="game">
   115	  <div class="board" data-testid="board" id="board">
   116	    <div class="overlay" id="overlay" hidden>
   117	      <div>Game over</div>
   118	      <button type="button" id="restart">Play again</button>
   119	    </div>
   120	  </div>
   121	  <div class="side">
   122	    <div class="box">
   123	      <div class="label">Score</div>
   124	      <div class="value" data-testid="score" id="score">0</div>
   125	    </div>
   126	    <div class="box">
   127	      <div class="label">Level</div>
   128	      <div class="value" data-testid="level" id="level">1</div>
   129	    </div>
   130	    <div class="box">
   131	      <div class="label">Lines</div>
   132	      <div class="value" data-testid="lines" id="lines">0</div>
   133	    </div>
   134	    <div class="box">
   135	      <div class="label">Next</div>
   136	      <div class="preview" id="preview"></div>
   137	    </div>
   138	    <div class="box help">
   139	      <div><kbd>←</kbd> <kbd>→</kbd> Move</div>
   140	      <div><kbd>↑</kbd> <kbd>X</kbd> Rotate</div>
   141	      <div><kbd>↓</kbd> Soft drop</div>
   142	      <div><kbd>Space</kbd> Hard drop</div>
   143	    </div>
   144	  </div>
   145	</div>
   146	
   147	<script>
   148	(function () {
   149	  "use strict";
   150	
   151	  var ROWS = 20;
   152	  var COLS = 10;
   153	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
   154	
   155	  // Spawn shapes as [row, col] offsets. Top row of every shape is row 0.
   156	  var SHAPES = {
   157	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
   158	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
   159	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
   160	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
   161	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
   162	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
   163	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
   164	  };
   165	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
   166	
   167	  // The I piece has its own rotation states so it turns in place like the
   168	  // guideline piece, without ever reaching above the piece's own row.
   169	  var I_STATES = [
   170	    [[0, 0], [0, 1], [0, 2], [0, 3]],
   171	    [[0, 2], [1, 2], [2, 2], [3, 2]],
   172	    [[1, 0], [1, 1], [1, 2], [1, 3]],
   173	    [[0, 1], [1, 1], [2, 1], [3, 1]]
   174	  ];
   175	  // Sideways shifts tried, in order, when a rotated shape does not fit.
   176	  var KICKS = [0, -1, 1, -2, 2];
   177	
   178	  // Locking rule.
   179	  var LOCK_DELAY = 2;      // gravity ticks a piece may spend unable to fall
   180	  var MAX_LOCK_RESETS = 3; // times a piece may restart its lock delay
   181	
   182	  // ---- State ----
   183	  var board;       // ROWS x COLS array of piece letters or null
   184	  var current;     // { type, row, col, rot, shape, lockTicks, lockResets } or null
   185	  var queue;       // upcoming piece letters, soonest first
   186	  var bag;         // 7-bag for the random generator
   187	  var score, level, lines, status;
   188	  var timer = null;
   189	
   190	  function emptyBoard() {
   191	    var b = [];
   192	    for (var r = 0; r < ROWS; r++) {
   193	      var row = [];
   194	      for (var c = 0; c < COLS; c++) row.push(null);
   195	      b.push(row);
   196	    }
   197	    return b;
   198	  }
   199	
   200	  function randomPiece() {
   201	    if (!bag || bag.length === 0) {
   202	      bag = TYPES.slice();
   203	      for (var i = bag.length - 1; i > 0; i--) {
   204	        var j = Math.floor(Math.random() * (i + 1));
   205	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
   206	      }
   207	    }
   208	    return bag.pop();
   209	  }
   210	
   211	  function sanitizeQueue(q) {
   212	    if (!Array.isArray(q)) return [];
   213	    return q.map(function (x) { return String(x).toUpperCase(); })
   214	            .filter(function (x) { return TYPES.indexOf(x) !== -1; });
   215	  }
   216	
   217	  // Keep at least one upcoming piece so there is always something to preview.
   218	  function fillQueue() {
   219	    while (queue.length < 1) queue.push(randomPiece());
   220	  }
   221	
   222	  function pieceCells(p, dRow, dCol) {
   223	    var out = [];
   224	    for (var i = 0; i < p.shape.length; i++) {
   225	      out.push([p.row + p.shape[i][0] + (dRow || 0), p.col + p.shape[i][1] + (dCol || 0)]);
   226	    }
   227	    return out;
   228	  }
   229	
   230	  function fits(p, dRow, dCol) {
   231	    var cells = pieceCells(p, dRow, dCol);
   232	    for (var i = 0; i < cells.length; i++) {
   233	      var r = cells[i][0], c = cells[i][1];
   234	      if (c < 0 || c >= COLS || r >= ROWS) return false;
   235	      if (r >= 0 && board[r][c]) return false;
   236	    }
   237	    return true;
   238	  }
   239	
   240	  function spawn() {
   241	    fillQueue();
   242	    var type = queue.shift();
   243	    fillQueue();
   244	    var p = {
   245	      type: type, row: 0, col: SPAWN_COL[type], rot: 0, shape: SHAPES[type],
   246	      lockTicks: 0, lockResets: 0
   247	    };
   248	    if (!fits(p, 0, 0)) {
   249	      current = null;
   250	      status = "over";
   251	      stopTimer();
   252	      return;
   253	    }
   254	    current = p;
   255	  }
   256	
   257	  function lock() {
   258	    var cells = pieceCells(current, 0, 0);
   259	    for (var i = 0; i < cells.length; i++) {
   260	      var r = cells[i][0], c = cells[i][1];
   261	      if (r >= 0 && r < ROWS && c >= 0 && c < COLS) board[r][c] = current.type;
   262	    }
   263	    current = null;
   264	    spawn();
   265	  }
   266	
   267	  // One gravity step. The real timer, tick() and soft drop all run this.
   268	  // If the piece cannot fall, the step counts one tick of lock delay instead.
   269	  function gravityStep() {
   270	    if (status !== "running" || !current) return;
   271	    if (fits(current, 1, 0)) {
   272	      current.row += 1;
   273	      current.lockTicks = 0;
   274	    } else {
   275	      current.lockTicks += 1;
   276	      if (current.lockTicks >= LOCK_DELAY) lock();
   277	    }
   278	  }
   279	
   280	  // A sideways move while resting restarts the lock delay, up to
   281	  // MAX_LOCK_RESETS times per piece.
   282	  function move(dCol) {
   283	    if (status !== "running" || !current) return;
   284	    if (!fits(current, 0, dCol)) return;
   285	    var resting = !fits(current, 1, 0);
   286	    current.col += dCol;
   287	    if (resting && current.lockResets < MAX_LOCK_RESETS) {
   288	      current.lockResets += 1;
   289	      current.lockTicks = 0;
   290	    }
   291	  }
   292	
   293	  function rotatedShape(p) {
   294	    var rot = (p.rot + 1) % 4;
   295	    if (p.type === "I") return { rot: rot, shape: I_STATES[rot] };
   296	    var size = p.type === "O" ? 2 : 3;
   297	    return {
   298	      rot: rot,
   299	      shape: p.shape.map(function (off) { return [off[1], size - 1 - off[0]]; })
   300	    };
   301	  }
   302	
   303	  // Rotate clockwise. If the turned shape does not fit, try shifting it
   304	  // sideways; if nothing fits, leave the piece exactly as it was.
   305	  function rotateCW() {
   306	    if (status !== "running" || !current) return;
   307	    var next = rotatedShape(current);
   308	    var trial = { row: current.row, col: current.col, shape: next.shape };
   309	    for (var i = 0; i < KICKS.length; i++) {
   310	      if (fits(trial, 0, KICKS[i])) {
   311	        current.col += KICKS[i];
   312	        current.rot = next.rot;
   313	        current.shape = next.shape;
   314	        return;
   315	      }
   316	    }
   317	  }
   318	
   319	  function hardDrop() {
   320	    if (status !== "running" || !current) return;
   321	    while (fits(current, 1, 0)) current.row += 1;
   322	    lock();
   323	  }
   324	
   325	  var ACTIONS = {
   326	    left: function () { move(-1); },
   327	    right: function () { move(1); },
   328	    rotateCW: rotateCW,
   329	    softDrop: gravityStep,
   330	    hardDrop: hardDrop
   331	  };
   332	
   333	  // ---- Timer ----
   334	  function gravityInterval() {
   335	    return Math.max(100, 1000 - (level - 1) * 100);
   336	  }
   337	
   338	  function onTimer() {
   339	    gravityStep();
   340	    render();
   341	  }
   342	
   343	  function startTimer() {
   344	    stopTimer();
   345	    timer = setInterval(onTimer, gravityInterval());
   346	  }
   347	
   348	  function stopTimer() {
   349	    if (timer !== null) {
   350	      clearInterval(timer);
   351	      timer = null;
   352	    }
   353	  }
   354	
   355	  // ---- Rendering (synchronous) ----
   356	  var boardEl = document.getElementById("board");
   357	  var overlayEl = document.getElementById("overlay");
   358	  var scoreEl = document.getElementById("score");
   359	  var levelEl = document.getElementById("level");
   360	  var linesEl = document.getElementById("lines");
   361	  var previewEl = document.getElementById("preview");
   362	  var cellEls = [];
   363	  var previewEls = [];
   364	
   365	  (function buildDom() {
   366	    for (var r = 0; r < ROWS; r++) {
   367	      var row = [];
   368	      for (var c = 0; c < COLS; c++) {
   369	        var el = document.createElement("div");
   370	        el.className = "cell";
   371	        el.setAttribute("data-testid", "cell");
   372	        el.setAttribute("data-row", String(r));
   373	        el.setAttribute("data-col", String(c));
   374	        el.setAttribute("data-filled", "false");
   375	        el.setAttribute("data-piece", "");
   376	        boardEl.insertBefore(el, overlayEl);
   377	        row.push(el);
   378	      }
   379	      cellEls.push(row);
   380	    }
   381	    for (var i = 0; i < 8; i++) {
   382	      var m = document.createElement("div");
   383	      m.className = "mini";
   384	      previewEl.appendChild(m);
   385	      previewEls.push(m);
   386	    }
   387	  })();
   388	
   389	  function setCell(el, type) {
   390	    var piece = type || "";
   391	    if (el.getAttribute("data-piece") === piece) return;
   392	    el.className = piece ? "cell p-" + piece : "cell";
   393	    el.setAttribute("data-filled", piece ? "true" : "false");
   394	    el.setAttribute("data-piece", piece);
   395	  }
   396	
   397	  function render() {
   398	    var view = board.map(function (row) { return row.slice(); });
   399	    if (current) {
   400	      var cells = pieceCells(current, 0, 0);
   401	      for (var i = 0; i < cells.length; i++) {
   402	        var r = cells[i][0], c = cells[i][1];
   403	        if (r >= 0 && r < ROWS && c >= 0 && c < COLS) view[r][c] = current.type;
   404	      }
   405	    }
   406	    for (var rr = 0; rr < ROWS; rr++) {
   407	      for (var cc = 0; cc < COLS; cc++) setCell(cellEls[rr][cc], view[rr][cc]);
   408	    }
   409	
   410	    scoreEl.textContent = String(score);
   411	    levelEl.textContent = String(level);
   412	    linesEl.textContent = String(lines);
   413	
   414	    for (var k = 0; k < previewEls.length; k++) previewEls[k].className = "mini";
   415	    var nextType = queue[0];
   416	    if (nextType) {
   417	      SHAPES[nextType].forEach(function (off) {
   418	        previewEls[off[0] * 4 + off[1]].className = "mini p-" + nextType;
   419	      });
   420	    }
   421	
   422	    overlayEl.hidden = status !== "over";
   423	  }
   424	
   425	  // ---- Game control ----
   426	  function newGame(q) {
   427	    board = emptyBoard();
   428	    bag = [];
   429	    queue = sanitizeQueue(q);
   430	    score = 0;
   431	    level = 1;
   432	    lines = 0;
   433	    status = "running";
   434	    current = null;
   435	    spawn();
   436	    if (status === "running") startTimer();
   437	    render();
   438	  }
   439	
   440	  function parseRows(rows) {
   441	    var b = emptyBoard();
   442	    if (!Array.isArray(rows)) return b;
   443	    for (var r = 0; r < ROWS && r < rows.length; r++) {
   444	      var line = String(rows[r]);
   445	      for (var c = 0; c < COLS && c < line.length; c++) {
   446	        var ch = line.charAt(c).toUpperCase();
   447	        b[r][c] = TYPES.indexOf(ch) !== -1 ? ch : null;
   448	      }
   449	    }
   450	    return b;
   451	  }
   452	
   453	  function boardToRows() {
   454	    return board.map(function (row) {
   455	      return row.map(function (v) { return v || "."; }).join("");
   456	    });
   457	  }
   458	
   459	  // ---- Keyboard ----
   460	  var KEYS = {
   461	    ArrowLeft: "left",
   462	    ArrowRight: "right",
   463	    ArrowUp: "rotateCW",
   464	    x: "rotateCW",
   465	    X: "rotateCW",
   466	    ArrowDown: "softDrop",
   467	    " ": "hardDrop",
   468	    Spacebar: "hardDrop"
   469	  };
   470	
   471	  document.addEventListener("keydown", function (e) {
   472	    if (status === "over" && e.key === "Enter") {
   473	      e.preventDefault();
   474	      newGame();
   475	      return;
   476	    }
   477	    var action = KEYS[e.key];
   478	    if (!action) return;
   479	    e.preventDefault();
   480	    ACTIONS[action]();
   481	    render();
   482	  });
   483	
   484	  document.getElementById("restart").addEventListener("click", function () {
   485	    newGame();
   486	  });
   487	
   488	  // ---- Test control surface ----
   489	  window.__tetris = {
   490	    newGame: function (q) { newGame(q); },
   491	    setQueue: function (q) {
   492	      queue = sanitizeQueue(q);
   493	      fillQueue();
   494	      render();
   495	    },
   496	    setBoard: function (rows) {
   497	      board = parseRows(rows);
   498	      render();
   499	    },
   500	    tick: function (n) {
   501	      var count = n === undefined ? 1 : Math.max(0, Math.floor(Number(n)) || 0);
   502	      for (var i = 0; i < count; i++) gravityStep();
   503	      render();
   504	    },
   505	    input: function (action) {
   506	      var fn = ACTIONS[action];
   507	      if (!fn) return;
   508	      fn();
   509	      render();
   510	    },
   511	    getBoard: function () { return boardToRows(); },
   512	    getState: function () {
   513	      return {
   514	        current: current ? { type: current.type, cells: pieceCells(current, 0, 0) } : null,
   515	        next: queue.slice(),
   516	        score: score,
   517	        level: level,
   518	        lines: lines,
   519	        status: status
   520	      };
   521	    }
   522	  };
   523	
   524	  newGame();
   525	})();
   526	</script>
   527	</body>
   528	</html>
